import type { GameState, Faction, BuildingType, UnitType } from './types';
import { createInitialState, tickSimulation, issueOrder, selectEntities, boxSelect, setControlGroup, recallControlGroup, togglePause, cycleSpeed, trainUnit, startConstruction, canBuildAt } from './sim';
import { createRenderContext, render, renderMinimap, drawSelectionBox, drawHUD, screenToWorld, getBuildPreview } from './render';
import type { RenderContext } from './render';
import { attachInput, createInputState, getBuildPreview as inputGetBuildPreview } from './input';
import type { InputState } from './input';
import { createUI, updateSelectionPanel, showWinLose, updateMinimap } from './ui';
import { mulberry32, hashSeed } from './rng';
import { MAP_SIZES, NUM_LEVELS, TILE_PX, VIEW_W, VIEW_H, SIM_DT, MINIMAP_SIZE } from './constants';
import { BUILDING_DATA } from './data';

const canvas = document.getElementById('game') as HTMLCanvasElement;
const root = document.getElementById('root')!;

let state: GameState;
let rc: RenderContext;
let input: InputState;
let ui: ReturnType<typeof createUI>;
let lastTime = performance.now();
let acc = 0;
let raf = 0;

let currentLevel = 0;
let unlockedLevels = 1; // start with level 1
let campaignSeed = 424242;

function getUrlSeed(): number | null {
  const p = new URLSearchParams(location.search);
  const s = p.get('seed');
  if (s) {
    const n = parseInt(s, 10);
    if (!isNaN(n)) return n >>> 0;
  }
  return null;
}

function startLevel(level: number, playerFaction: Faction, seedOverride?: number) {
  const seed = seedOverride ?? (getUrlSeed() ?? hashSeed(campaignSeed, level * 31 + 7));
  state = createInitialState(level, playerFaction, seed);
  rc.camX = state.camX;
  rc.camY = state.camY;

  // reset input
  input.buildMode = null;
  state.selectedIds.clear();

  // hide any win/lose
  const existing = root.querySelectorAll('.winlose, .menu');
  existing.forEach(el => el.remove());

  // kick off loop if needed
  if (!raf) gameLoop();
}

function showMainMenu() {
  cancelAnimationFrame(raf);
  raf = 0;

  const menu = document.createElement('div');
  menu.className = 'menu';

  const title = document.createElement('h1');
  title.textContent = 'WARBAND';
  menu.appendChild(title);

  const subtitle = document.createElement('div');
  subtitle.textContent = 'Real-Time Strategy • WFC Maps • Seeded';
  subtitle.style.marginBottom = '18px';
  subtitle.style.color = '#888';
  menu.appendChild(subtitle);

  // Faction picker + start buttons
  const facRow = document.createElement('div');
  facRow.style.margin = '12px 0 16px';
  facRow.style.display = 'flex';
  facRow.style.gap = '12px';
  facRow.style.justifyContent = 'center';

  let chosenFaction: Faction = 'human';

  const humanBtn = document.createElement('button');
  humanBtn.textContent = 'HUMANS';
  humanBtn.style.borderColor = '#3a6db5';
  humanBtn.onclick = () => { chosenFaction = 'human'; refreshFac(); };
  const orcBtn = document.createElement('button');
  orcBtn.textContent = 'ORCS';
  orcBtn.style.borderColor = '#3f6f3f';
  orcBtn.onclick = () => { chosenFaction = 'orc'; refreshFac(); };

  function refreshFac() {
    humanBtn.style.background = chosenFaction === 'human' ? '#3a6db5' : '#222';
    orcBtn.style.background = chosenFaction === 'orc' ? '#3f6f3f' : '#222';
    humanBtn.style.color = '#fff';
    orcBtn.style.color = '#fff';
  }
  refreshFac();

  facRow.appendChild(humanBtn);
  facRow.appendChild(orcBtn);
  menu.appendChild(facRow);

  const startBtn = document.createElement('button');
  startBtn.textContent = 'START CAMPAIGN';
  startBtn.onclick = () => {
    menu.remove();
    currentLevel = 0;
    unlockedLevels = 1;
    startLevel(0, chosenFaction);
  };
  menu.appendChild(startBtn);

  // Level select
  const levelTitle = document.createElement('div');
  levelTitle.textContent = 'LEVEL SELECT';
  levelTitle.style.margin = '22px 0 6px';
  levelTitle.style.fontSize = '13px';
  levelTitle.style.color = '#888';
  menu.appendChild(levelTitle);

  const levelsDiv = document.createElement('div');
  levelsDiv.className = 'level';

  for (let i = 0; i < NUM_LEVELS; i++) {
    const lb = document.createElement('button');
    lb.className = 'level-btn';
    lb.textContent = String(i + 1);
    if (i >= unlockedLevels) {
      lb.classList.add('locked');
      lb.textContent += ' 🔒';
      lb.onclick = () => {};
    } else {
      lb.onclick = () => {
        menu.remove();
        currentLevel = i;
        startLevel(i, chosenFaction);
      };
    }
    levelsDiv.appendChild(lb);
  }
  menu.appendChild(levelsDiv);

  const seedInfo = document.createElement('div');
  seedInfo.style.marginTop = '24px';
  seedInfo.style.fontSize = '10px';
  seedInfo.style.color = '#555';
  seedInfo.textContent = `Seed: ${campaignSeed}  •  ?seed=XXXXXX in URL overrides`;
  menu.appendChild(seedInfo);

  root.appendChild(menu);
}

function gameLoop() {
  const now = performance.now();
  let frameTime = now - lastTime;
  lastTime = now;
  if (frameTime > 120) frameTime = 120; // clamp spiral

  acc += frameTime;

  const stepsPerFrame = state ? state.speed : 1;
  const targetSteps = Math.floor(acc / SIM_DT);

  if (state && !state.paused && state.gameOver === 'none') {
    const doSteps = Math.min(targetSteps, 6); // safety
    if (doSteps > 0) {
      tickSimulation(state, doSteps * stepsPerFrame);
      acc -= doSteps * SIM_DT;
    }
  } else {
    acc = 0;
  }

  // camera sync
  if (state) {
    state.camX = rc.camX;
    state.camY = rc.camY;
  }

  // render
  if (state) {
    const buildPrev = inputGetBuildPreview(state, input, rc);
    render(rc, state, undefined, buildPrev);

    // draw drag selection box
    if (input.isDragging && input.mouseDown) {
      drawSelectionBox(rc.ctx, input.dragStartX, input.dragStartY, input.mouseX, input.mouseY);
    }

    drawHUD(rc.ctx, state, rc.w);

    // minimap
    const mm = ui.minimap as HTMLCanvasElement;
    const mmCtx = mm.getContext('2d')!;
    renderMinimap(mmCtx, state, 160, 0, 0);

    // selection panel
    updateSelectionPanel(ui.panel, state, (bt: BuildingType) => {
      // enter build mode
      input.buildMode = bt;
    }, (ut: UnitType) => {
      const ok = trainUnit(state, ut);
      // no feedback sound, just visual
    });

    // status
    const statusEl = document.getElementById('status')!;
    if (state.gameOver !== 'none') {
      statusEl.classList.remove('hidden');
      statusEl.textContent = state.gameOver.toUpperCase();
      statusEl.style.color = state.gameOver === 'victory' ? '#5f5' : '#f55';
    } else {
      statusEl.classList.add('hidden');
    }

    // win/lose modal
    if (state.gameOver !== 'none') {
      const exists = root.querySelector('.winlose');
      if (!exists) {
        showWinLose(root, state, (next: boolean) => {
          if (next && state.gameOver === 'victory') {
            unlockedLevels = Math.max(unlockedLevels, state.level + 2);
            currentLevel = Math.min(NUM_LEVELS - 1, state.level + 1);
            const nextSeed = hashSeed(campaignSeed, currentLevel * 31 + 7);
            startLevel(currentLevel, state.playerFaction, nextSeed);
          } else {
            startLevel(state.level, state.playerFaction);
          }
        });
      }
    }
  }

  // handle build preview cursor style
  if (input.buildMode) {
    canvas.style.cursor = 'crosshair';
  } else {
    canvas.style.cursor = input.hoveredEntityId ? 'pointer' : 'default';
  }

  raf = requestAnimationFrame(gameLoop);
}

// Global controls for keyboard
(window as any).__warbandTogglePause = () => {
  if (state) {
    togglePause(state);
  }
};
(window as any).__warbandCycleSpeed = () => {
  if (state) cycleSpeed(state);
};

// Boot
function boot() {
  rc = createRenderContext(canvas);
  input = createInputState();
  ui = createUI(root, null as any, () => {});

  // Attach input handlers
  attachInput(
    canvas,
    rc,
    null as any, // will be rebound on level start
    input,
    (bt: BuildingType, fx: number, fy: number) => {
      if (!state) return;
      // attempt immediate construction (worker order happens via right-click usually)
      const ok = startConstruction(state, bt, fx, fy);
      if (ok) {
        // if we spent, auto-order nearest worker to it (if selected or idle)
        const workers = Array.from(state.entities.values()).filter(
          e => e.faction === state.playerFaction && e.type === 'worker' && e.order === 'idle'
        );
        if (workers.length > 0) {
          const nearest = workers.reduce((a, b) =>
            Math.hypot(a.pos.x - fx - 0.5, a.pos.y - fy - 0.5) <
            Math.hypot(b.pos.x - fx - 0.5, b.pos.y - fy - 0.5) ? a : b
          );
          // issue build order to nearest
          issueOrder(state, { type: 'build', pos: { x: fx + 0.5, y: fy + 0.5 }, buildingType: bt });
          // move the chosen one explicitly
          selectEntities(state, [nearest.id], false);
        }
      }
      input.buildMode = null;
    },
    (ut: UnitType) => {
      if (state) trainUnit(state, ut);
    },
    () => ui.panel
  );

  // initial camera position
  rc.camX = 3;
  rc.camY = 3;

  // Start at main menu
  showMainMenu();

  // Expose for debugging
  (window as any).warband = {
    getState: () => state,
    setSpeed: (s: 1|2) => { if (state) state.speed = s; },
    forceTick: (n = 1) => { if (state) tickSimulation(state, n); }
  };

  // Keyboard global pause/speed already wired via the __warband* hooks
  // Bonus: click outside canvas etc handled naturally
}

boot();

import { describe, it, expect } from 'vitest';
import { runWFC, countTiles } from '../src/wfc';
import { mulberry32 } from '../src/rng';
import type { Tile } from '../src/types';

describe('WFC map generation', () => {
  it('produces consistent output for identical seed', () => {
    const rng1 = mulberry32(12345);
    const rng2 = mulberry32(12345);
    const r1 = runWFC({ width: 24, height: 24, rng: rng1, maxAttempts: 5 });
    const r2 = runWFC({ width: 24, height: 24, rng: rng2, maxAttempts: 5 });
    expect(r1.success).toBe(r2.success);
    expect(r1.tiles).toEqual(r2.tiles);
  });

  it('respects basic adjacency constraints (no water directly next to goldmine without dirt)', () => {
    const rng = mulberry32(99991);
    const res = runWFC({ width: 28, height: 28, rng, maxAttempts: 6 });
    const tiles = res.tiles;
    const w = tiles[0].length;
    const h = tiles.length;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const t = tiles[y][x];
        if (t === 'goldmine') {
          // check 4 cardinal neighbors
          const dirs = [[0,-1],[1,0],[0,1],[-1,0]];
          for (const [dx,dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx>=0&&ny>=0&&nx<w&&ny<h) {
              const n = tiles[ny][nx];
              expect(['grass','dirt','forest'].includes(n)).toBe(true);
            }
          }
        }
        if (t === 'water') {
          const dirs = [[0,-1],[1,0],[0,1],[-1,0]];
          for (const [dx,dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx>=0&&ny>=0&&nx<w&&ny<h) {
              const n = tiles[ny][nx];
              expect(['water','dirt'].includes(n)).toBe(true);
            }
          }
        }
      }
    }
  });

  it('generates a usable number of grass/dirt for playability', () => {
    const rng = mulberry32(777);
    const res = runWFC({ width: 32, height: 32, rng, maxAttempts: 5 });
    const cnt = countTiles(res.tiles);
    const walkable = (cnt.grass || 0) + (cnt.dirt || 0) + (cnt.goldmine || 0);
    expect(walkable).toBeGreaterThan(280);
  });
});

import { describe, it, expect } from 'vitest';
import { findPath, buildWalkGrid } from '../src/pathfind';
import type { Tile } from '../src/types';

describe('A* pathfinding', () => {
  function makeGridFromTiles(tiles: Tile[][]): boolean[][] {
    return buildWalkGrid(tiles as any, tiles[0].length, tiles.length);
  }

  it('finds a direct shortest path on open field', () => {
    const tiles: Tile[][] = Array.from({ length: 12 }, () =>
      Array.from({ length: 12 }, () => 'grass' as Tile)
    );
    const grid = makeGridFromTiles(tiles);
    const path = findPath(grid, { x: 1.5, y: 1.5 }, { x: 9.5, y: 9.5 }, 12, 12);
    expect(path).not.toBeNull();
    expect(path!.length).toBeGreaterThan(3);
    // last point approx goal
    const last = path![path!.length - 1];
    expect(Math.abs(last.x - 9.5)).toBeLessThan(0.6);
    expect(Math.abs(last.y - 9.5)).toBeLessThan(0.6);
  });

  it('avoids water and rock, does not corner cut', () => {
    const tiles: Tile[][] = Array.from({ length: 10 }, () =>
      Array.from({ length: 10 }, () => 'grass' as Tile)
    );
    // block a diagonal corridor
    tiles[4][4] = 'water';
    tiles[4][5] = 'water';
    tiles[5][4] = 'water';
    tiles[5][5] = 'rock';

    const grid = makeGridFromTiles(tiles);
    const path = findPath(grid, { x: 2, y: 2 }, { x: 7, y: 7 }, 10, 10);
    expect(path).not.toBeNull();
    // Verify no path goes through blocked tiles
    if (path) {
      for (let i = 0; i < path.length; i++) {
        const p = path[i];
        const tx = Math.floor(p.x);
        const ty = Math.floor(p.y);
        expect(['water', 'rock'].includes(tiles[ty][tx] as any)).toBe(false);
      }
    }
  });

  it('returns null for unreachable goal', () => {
    const tiles: Tile[][] = Array.from({ length: 8 }, () =>
      Array.from({ length: 8 }, () => 'grass' as Tile)
    );
    for (let x=0; x<8; x++) tiles[3][x] = 'water'; // wall
    const grid = makeGridFromTiles(tiles);
    const path = findPath(grid, { x: 1, y: 1 }, { x: 4, y: 5 }, 8, 8);
    expect(path).toBeNull();
  });

  it('produces 8-directional moves without illegal corner cuts', () => {
    const tiles: Tile[][] = Array.from({ length: 6 }, (_, y) =>
      Array.from({ length: 6 }, (_, x) => (x === 2 && y === 2 ? 'rock' : 'grass') as Tile)
    );
    const grid = makeGridFromTiles(tiles);
    const path = findPath(grid, { x: 0.5, y: 0.5 }, { x: 5.5, y: 5.5 }, 6, 6);
    expect(path).not.toBeNull();
    // check that any diagonal step had supporting cardinals
    if (path && path.length >= 2) {
      for (let i = 1; i < path.length; i++) {
        const a = path[i - 1];
        const b = path[i];
        const dx = Math.round(b.x - a.x);
        const dy = Math.round(b.y - a.y);
        if (Math.abs(dx) === 1 && Math.abs(dy) === 1) {
          // both straight steps must be possible in original grid
          const mx = Math.round(a.x + dx);
          const my = Math.round(a.y);
          const nx = Math.round(a.x);
          const ny = Math.round(a.y + dy);
          expect(grid[my][mx]).toBe(true);
          expect(grid[ny][nx]).toBe(true);
        }
      }
    }
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { createInitialState, createUnit, canAfford, spend, trainUnit, tickSimulation } from '../src/sim';
import type { GameState, Faction } from '../src/types';
import { UNIT_DATA } from '../src/data';
import { SUPPLY_TH, SUPPLY_FARM } from '../src/constants';

describe('Combat damage and supply', () => {
  let state: GameState;

  beforeEach(() => {
    state = createInitialState(0, 'human', 123456);
  });

  it('applies damage correctly with armor (min 1)', () => {
    // create two units
    const inf = createUnit(state, 'human', 'inf', 5, 5);
    const ranged = createUnit(state, 'orc', 'ranged', 6.5, 5);

    const beforeHp = inf.hp;
    // simulate a direct attack by orc ranged (damage 6 - armor 2 = 4)
    // We call internal logic indirectly: force a projectile or melee
    // For unit test we manually invoke the damage function via tick if possible, or expose apply.
    // Since applyDamage is not exported, we will tick until attack happens or use public API.
    // Simpler: force cooldown and call handleAttack conceptually.
    // Instead we test the math via exported behavior: train and observe supply, then do manual tick.
    const dmg = 6; // ranged
    const armor = UNIT_DATA.human.inf.armor; // 2
    const expected = Math.max(1, dmg - armor);
    expect(expected).toBe(4);
    // Now apply via internal: spawn a projectile and tick
    state.projectiles.push({
      id: 9999,
      pos: { x: ranged.pos.x, y: ranged.pos.y },
      vel: { x: 0, y: 0 },
      damage: dmg,
      ownerFaction: 'orc',
      targetId: inf.id,
      life: 5,
    });
    tickSimulation(state, 6);
    expect(inf.hp).toBeLessThanOrEqual(beforeHp - 3);
    expect(inf.hp).toBeGreaterThanOrEqual(beforeHp - 6);
  });

  it('blocks training when supply cap reached', () => {
    const fac: Faction = 'human';
    // start supply is TH + FARM = 16, 1 worker already
    expect(state.supplyCap[fac]).toBe(SUPPLY_TH + SUPPLY_FARM);
    expect(state.supplyUsed[fac]).toBe(1);

    // train workers until almost full
    let trained = 0;
    while (canAfford(state, fac, 65, 0, 1) && trained < 20) {
      const ok = trainUnit(state, 'worker');
      if (!ok) break;
      trained++;
    }
    const used = state.supplyUsed[fac];
    expect(used).toBeLessThanOrEqual(state.supplyCap[fac]);
    // next should fail
    const beforeGold = state.gold[fac];
    const could = trainUnit(state, 'worker');
    expect(could).toBe(false);
    expect(state.gold[fac]).toBe(beforeGold);
  });

  it('grants supply when farm is constructed (via build progress)', () => {
    const fac: Faction = state.playerFaction;
    const beforeCap = state.supplyCap[fac];
    // manually create farm under construction
    // Use startConstruction + advance time
    const ok = startConstruction(state, 'farm', 10, 8);
    expect(ok).toBe(true);

    // simulate workers building it: find the farm
    let farm = Array.from(state.entities.values()).find(e => e.kind === 'building' && e.type === 'farm') as any;
    expect(farm).toBeTruthy();

    // tick enough for build time (farm buildTime ~80)
    for (let i = 0; i < 100; i++) {
      // simulate a worker on it
      const worker = Array.from(state.entities.values()).find(e => e.type === 'worker' && e.faction === fac);
      if (worker) {
        worker.order = 'build';
        worker.buildType = 'farm';
        worker.targetPos = { x: farm.pos.x, y: farm.pos.y };
      }
      tickSimulation(state, 1);
    }
    farm = Array.from(state.entities.values()).find(e => e.kind === 'building' && e.type === 'farm') as any;
    if (farm) {
      expect(farm.isBuilt).toBe(true);
      expect(state.supplyCap[fac]).toBeGreaterThan(beforeCap);
    }
  });

  it('removes supply cost when unit dies', () => {
    const fac: Faction = 'human';
    const beforeUsed = state.supplyUsed[fac];
    const w = createUnit(state, fac, 'worker', 12, 9);
    expect(state.supplyUsed[fac]).toBe(beforeUsed + 1);
    // kill it
    w.hp = 0;
    tickSimulation(state, 3);
    expect(state.supplyUsed[fac]).toBe(beforeUsed);
    expect(state.entities.has(w.id)).toBe(false);
  });
});

